<script setup lang="ts">
import { onMounted, ref } from 'vue'
import NumberField from '@/components/ui/NumberField.vue'
import { api, errorMessage } from '@/lib/api'
import { toPersianDigits } from '@/lib/format'
import type { SetupStatus } from '@/lib/types/documents'
const status = ref<SetupStatus | null>(null), error = ref(''), busy = ref(false), serialStart = ref<number | null>(null), baleTerm = ref(0), confirmSampleRates = ref(false), report = ref<string[]>([])
async function load() { try { status.value = await api.get('/api/settings/setup-status') } catch (e) { error.value = errorMessage(e) } }
async function apply() { busy.value = true; error.value = ''; try { report.value = (await api.post<{ items: string[] }>('/api/settings/presets/export-rugs', { serialStart: serialStart.value, baleTerm: baleTerm.value, confirmSampleRates: confirmSampleRates.value })).items; await load() } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(load)
</script>
<template><section class="space-y-5 py-4" :aria-busy="busy"><p v-if="error" role="alert" class="text-error">{{ error }}</p><p v-if="status" class="text-xl font-bold" role="status">{{ status.ready ? 'آماده است' : `${toPersianDigits(String(status.remaining))} کار تا آماده شدن مانده` }}</p><details class="rounded-xl border border-outline-variant bg-surface-container p-4" :open="!status?.steps.find(s => s.key === 'preset')?.done"><summary class="min-h-11 cursor-pointer font-bold">بستهٔ صادرات فرش</summary><div class="space-y-3"><p>ستون‌ها، نوع‌های هزینه، برچسب شماره و قالب‌های خروجی آماده می‌شوند. تنظیم‌های قبلی حفظ می‌شوند.</p><label class="block">شمارهٔ شروع<NumberField v-model="serialStart" kind="integer" :min="1" /></label><label class="block">نام بسته<select v-model="baleTerm" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2"><option :value="0">نگله</option><option :value="1">عدل</option></select></label><label class="flex min-h-11 items-center gap-3"><input v-model="confirmSampleRates" type="checkbox" class="h-6 w-6" />این نرخ‌ها نمونه‌اند؛ تأیید می‌کنم (گبه ۴۵، خراسان تجاری ۲۵، نائین ۹ لا ۸۰ دلار هر متر)</label><button :disabled="busy" class="min-h-11 rounded-lg bg-primary px-5 text-on-primary" @click="apply">اعمال بسته</button><ul aria-live="polite"><li v-for="item in report" :key="item">{{ item }}</li></ul></div></details><ol v-if="status" class="space-y-3"><li v-for="step in status.steps" :key="step.key" class="rounded-xl border border-outline-variant p-4"><a :href="step.href" class="inline-flex min-h-11 items-center gap-3 text-primary"><span aria-hidden="true">{{ step.done ? '✓' : '○' }}</span>{{ step.label }}<span v-if="!step.required" class="text-sm text-on-surface-variant">(اختیاری)</span><span class="sr-only">{{ step.done ? 'انجام شده' : 'باقی مانده' }}</span></a><p v-if="step.missing?.length" class="text-error">نرخ این محل‌ها ثبت نشده: {{ step.missing.join('، ') }}</p></li></ol><button class="min-h-11 px-4 text-primary" @click="load">بررسی دوباره</button></section></template>
